import java.util.StringTokenizer

fun main() {
    val st = StringTokenizer(readLine()!!)
    val n = st.nextToken().toLong()
    val k = st.nextToken().toLong()

    var left = 1L
    var right = n
    var ans: Long? = null

    while (left <= right) {
        val mid = (left + right) / 2
        var tmp = mid
        var sum = 0L

        while (tmp > 0) {
            sum += tmp
            tmp /= k
        }

        if (sum < n) {
            left = mid + 1
        } else {
            right = mid - 1
            ans = mid
        }
    }

    println(ans) 
}

